export type IconName = keyof typeof P
export const ICON_NAMES = Object.keys(P) as IconName[]

export interface MIconProps {
  name: IconName
  size?: number
  className?: string
  style?: CSSProperties
  /** testo per screen reader; se assente l'icona è decorativa */
  label?: string
}

export function MIcon({ name, size = 24, className, style, label }: MIconProps) {
  return (
    <svg
      className={'m3-icon' + (className ? ' ' + className : '')}
      width={size}
      height={size}
      viewBox="0 -960 960 960"
      fill="currentColor"
      style={style}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      focusable="false"
    >
      <path d={P[name]} />
    </svg>
  )
}
